// Graph topology IDs must be the identities emitted by the concrete Device, not local array positions. This keeps
// the native packet smoke paths honest across device recreation and distinct Compute/Transfer transports.
[[nodiscard]] static GpuPhysicalQueueId BackendQueueId(
    GraphicsBackend::Device& device,
    const CommandQueue::Enum queue
){
    return device.getPrimaryPhysicalQueue(queue);
}


// A graph declaration can name a known imported state only after native work has materialized that state. Fresh
// Vulkan images begin UNDEFINED, so tests that intentionally model an external first reader use this small producer
// instead of asserting a descriptor's logical initialState as physical truth.
[[nodiscard]] static bool PrimeTextureStatesForGraph(
    GraphicsBackend::Device& device,
    Texture* const* const textures,
    const usize textureCount,
    const ResourceStates::Mask state
){
    if(!textures || textureCount == 0u || state == ResourceStates::Unknown)
        return false;
    for(usize textureIndex = 0u; textureIndex < textureCount; ++textureIndex){
        if(!textures[textureIndex])
            return false;
    }

    const auto commandList = device.createCommandList();
    if(!commandList)
        return false;
    commandList->open();
    for(usize textureIndex = 0u; textureIndex < textureCount; ++textureIndex)
        commandList->setTextureState(textures[textureIndex], s_AllSubresources, state);
    commandList->close();

    CommandList* const commandLists[] = { commandList.get() };
    const QueueSubmissionToken token = device.executeCommandLists(
        commandLists,
        LengthOf(commandLists),
        CommandQueue::Graphics,
        QueueSubmissionDesc{}
    );
    return token.valid() && device.waitForIdle();
}


// The UI compatibility path owns neither a renderer graph nor a native preparation list. This compact probe uses
// the public standalone submission boundary directly: an immutable upload must reach ShaderResource before the
// terminal callback accepts, while a rejected packet must discard that callback without publishing a token.
struct StandaloneGraphTextureUploadCompletionTask{
    struct Payload{
        GpuGraphResourceId texture;
        bool* recorded = nullptr;
        bool* accepted = nullptr;
        bool* discarded = nullptr;
    };

    [[nodiscard]] static bool record(
        const Payload& payload,
        CommandList& commandList,
        const GpuTaskRecordContext& context
    ){
        Texture* const texture = context.taskGraph.textureForResource(payload.texture);
        const bool ready = texture
            && commandList.getTextureSubresourceState(texture, 0u, 0u) == ResourceStates::ShaderResource
        ;
        if(payload.recorded)
            *payload.recorded = ready;
        return ready;
    }

    static void accepted(Payload& payload, const QueueSubmissionToken& token){
        if(payload.accepted)
            *payload.accepted = token.valid();
    }

    static void discarded(Payload& payload){
        if(payload.discarded)
            *payload.discarded = true;
    }
};

struct StandaloneGraphTextureUploadContext{
    TextureHandle destination;
    const void* bytes = nullptr;
    usize byteCount = 0u;
    usize rowPitch = 0u;
    bool* recorded = nullptr;
    bool* accepted = nullptr;
    bool* discarded = nullptr;
};

#if !defined(NWB_FINAL)
[[nodiscard]] static GpuTaskId DeclareStandaloneGraphTextureUpload(
    void* const rawContext,
    GpuTaskGraph& graph
){
    StandaloneGraphTextureUploadContext* const context =
        static_cast<StandaloneGraphTextureUploadContext*>(rawContext)
    ;
    if(!context || !context->destination || !context->bytes || context->byteCount == 0u)
        return {};

    const TextureDesc& textureDesc = context->destination->getDescription();
    const GpuGraphResourceId destination = graph.importTexture(
        context->destination,
        GpuGraphResourceDesc{}
            .setIdentity(Name("tests.standalone_graph_texture_upload.destination"))
            .setMarkerLabel("Standalone Graph Texture Upload")
            .setType(GpuGraphResourceType::Texture)
            // This probe creates the destination immediately before its graph-owned first write. The descriptor
            // state is the retained post-upload contract, while the native Vulkan image still starts Undefined.
            .setInitialState(ResourceStates::Unknown)
            .setQueueSharing(textureDesc.queueSharing)
    );
    const GpuUploadBlobId source = graph.copyUploadData(context->bytes, context->byteCount, alignof(u32));
    if(!destination.valid() || !source.valid())
        return {};

    GpuTaskSchedulingHint uploadScheduling;
    uploadScheduling.cost = GpuTaskCostHint::Tiny;
    uploadScheduling.forceSubmissionBoundary = true;
    uploadScheduling.allowPacketMerge = false;
    GpuTaskDesc uploadDesc;
    uploadDesc
        .setIdentity(Name("tests.standalone_graph_texture_upload.upload"))
        .setMarkerLabel("Standalone Graph Texture Upload")
        .setQueue(GpuQueueRequest{
            GpuQueueCapability::Transfer,
            GpuQueuePreference::Graphics,
            false,
            false,
        })
        .setScheduling(uploadScheduling)
    ;
    const GpuTaskId uploadTask = graph.addUploadTextureTask(
        uploadDesc,
        GpuUploadTextureTaskDesc{
            .source = source,
            .destination = destination,
            .arraySlice = 0u,
            .mipLevel = 0u,
            .rowPitch = context->rowPitch,
            .depthPitch = 0u,
            .finalState = ResourceStates::ShaderResource,
        }
    );
    if(!uploadTask.valid())
        return {};

    const GpuTaskResourceUse completionUses[] = {
        GpuTaskResourceUse{
            .resource = destination,
            .range = {},
            .requiredState = ResourceStates::ShaderResource,
            .access = GpuTaskResourceAccess::Read,
        },
    };
    GpuTaskSchedulingHint completionScheduling;
    completionScheduling.cost = GpuTaskCostHint::Tiny;
    completionScheduling.forceSubmissionBoundary = true;
    completionScheduling.allowPacketMerge = false;
    GpuTaskDesc completionDesc;
    completionDesc
        .setIdentity(Name("tests.standalone_graph_texture_upload.completion"))
        .setMarkerLabel("Standalone Graph Texture Upload Completion")
        .setQueue(GpuQueueRequest{
            GpuQueueCapability::Graphics,
            GpuQueuePreference::Graphics,
            false,
            false,
        })
        .setScheduling(completionScheduling)
        .setDependencies(&uploadTask, 1u)
        .setResourceUses(completionUses, LengthOf(completionUses))
    ;
    return graph.addTask<StandaloneGraphTextureUploadCompletionTask>(
        completionDesc,
        StandaloneGraphTextureUploadCompletionTask::Payload{
            .texture = destination,
            .recorded = context->recorded,
            .accepted = context->accepted,
            .discarded = context->discarded,
        }
    );
}
#endif

#if !defined(NWB_FINAL)
// The public standalone boundary normally owns no renderer tail.  This probe makes a Transfer packet accept before
// a dependent Graphics packet is rejected, then arms the backend's one-shot wait capture from that rejection so it
// observes the standalone helper's subsequently submitted recovery frontier exactly.
struct StandaloneGraphAcceptedFrontierRecoveryCompletionTask{
    struct Payload{
        GraphicsBackend::Device& device;
        bool* recorded = nullptr;
        bool* accepted = nullptr;
        bool* discarded = nullptr;
    };

    [[nodiscard]] static bool record(
        const Payload& payload,
        CommandList& commandList,
        const GpuTaskRecordContext& context
    ){
        static_cast<void>(commandList);
        static_cast<void>(context);
        if(payload.recorded)
            *payload.recorded = true;
        return true;
    }

    static void accepted(Payload& payload, const QueueSubmissionToken& token){
        if(payload.accepted)
            *payload.accepted = token.valid();
    }

    static void discarded(Payload& payload){
        if(payload.discarded)
            *payload.discarded = true;

        payload.device.clearSubmissionWaitTokensForTesting();
        payload.device.armSubmissionWaitCaptureForTesting();
    }
};

struct StandaloneGraphAcceptedFrontierRecoveryContext{
    BufferHandle destination;
    const void* bytes = nullptr;
    usize byteCount = 0u;
    GraphicsBackend::Device& device;
    QueueSubmissionToken* acceptedTransferToken = nullptr;
    bool* graphicsRecorded = nullptr;
    bool* graphicsAccepted = nullptr;
    bool* graphicsDiscarded = nullptr;
};

[[nodiscard]] static GpuTaskId DeclareStandaloneGraphAcceptedFrontierRecovery(
    void* const rawContext,
    GpuTaskGraph& graph
){
    StandaloneGraphAcceptedFrontierRecoveryContext* const context =
        static_cast<StandaloneGraphAcceptedFrontierRecoveryContext*>(rawContext)
    ;
    if(
        !context
        || !context->destination
        || !context->bytes
        || context->byteCount == 0u
    )
        return {};

    const GpuGraphResourceId destination = graph.importBuffer(
        context->destination,
        GpuGraphResourceDesc{}
            .setIdentity(Name("tests.standalone_graph_accepted_frontier_recovery.destination"))
            .setMarkerLabel("Standalone Accepted Frontier Recovery Destination")
            .setType(GpuGraphResourceType::Buffer)
            .setInitialState(ResourceStates::Common)
            .setQueueSharing(ResourceQueueSharing::GraphicsAndTransfer)
    );
    const GpuUploadBlobId source = graph.copyUploadData(context->bytes, context->byteCount, alignof(u32));
    if(!destination.valid() || !source.valid())
        return {};

    GpuTaskSchedulingHint packetScheduling;
    packetScheduling.cost = GpuTaskCostHint::Tiny;
    packetScheduling.overlapPreferred = false;
    packetScheduling.forceSubmissionBoundary = true;
    packetScheduling.allowPacketMerge = false;
    const GpuQueueRequest transferRequest{
        GpuQueueCapability::Transfer,
        GpuQueuePreference::Transfer,
        false,
        false,
    };
    const GpuQueueRequest graphicsRequest{
        GpuQueueCapability::Graphics,
        GpuQueuePreference::Graphics,
        false,
        false,
    };
    const GpuTaskId transferTask = graph.addUploadBufferTask(
        GpuTaskDesc{}
            .setIdentity(Name("tests.standalone_graph_accepted_frontier_recovery.transfer"))
            .setMarkerLabel("Standalone Accepted Frontier Recovery Transfer")
            .setQueue(transferRequest)
            .setScheduling(packetScheduling),
        GpuUploadBufferTaskDesc{
            .source = source,
            .destination = destination,
            .finalState = ResourceStates::CopyDest,
            .acceptedToken = context->acceptedTransferToken,
        }
    );
    if(!transferTask.valid())
        return {};

    const GpuTaskId suffixTask = graph.addTask<StandaloneGraphAcceptedFrontierRecoveryCompletionTask>(
        GpuTaskDesc{}
            .setIdentity(Name("tests.standalone_graph_accepted_frontier_recovery.graphics"))
            .setMarkerLabel("Standalone Accepted Frontier Recovery Graphics")
            .setQueue(graphicsRequest)
            .setScheduling(packetScheduling)
            .setDependencies(&transferTask, 1u),
        StandaloneGraphAcceptedFrontierRecoveryCompletionTask::Payload{
            .device = context->device,
            .recorded = context->graphicsRecorded,
            .accepted = context->graphicsAccepted,
            .discarded = context->graphicsDiscarded,
        }
    );
    return suffixTask;
}
#endif


// Public standalone declarations may opt into the same compiler-derived worker frontiers as renderer-owned graph
// tasks. This probe keeps both caller arrays mutable so the built-in uploads prove graph-owned blob retention, while
// two side-effect-free packet tasks prove the same ready frontier receives nonzero worker-affined leases.
struct StandaloneGraphReadyFrontierObserverTask{
    struct Payload{
        Latch* recordingStarted = nullptr;
        u32* observedWorkerIndex = nullptr;
        bool* discarded = nullptr;
    };

    [[nodiscard]] static bool record(
        const Payload& payload,
        CommandList& commandList,
        const GpuTaskRecordContext& context
    ){
        static_cast<void>(context);
        if(!payload.recordingStarted || !payload.observedWorkerIndex)
            return false;

        *payload.observedWorkerIndex = commandList.getDescription().recordingWorkerIndex;
        payload.recordingStarted->count_down();
        payload.recordingStarted->wait();
        return commandList.isRecording();
    }

    static void discarded(Payload& payload){
        if(payload.discarded)
            *payload.discarded = true;
    }
};

struct StandaloneGraphReadyFrontierUploadContext{
    BufferHandle firstDestination;
    BufferHandle secondDestination;
    void* firstBytes = nullptr;
    void* secondBytes = nullptr;
    usize firstByteCount = 0u;
    usize secondByteCount = 0u;
    Latch* recordingStarted = nullptr;
    u32* firstWorkerIndex = nullptr;
    u32* secondWorkerIndex = nullptr;
    QueueSubmissionToken* firstAcceptedToken = nullptr;
    QueueSubmissionToken* secondAcceptedToken = nullptr;
    bool* firstDiscarded = nullptr;
    bool* secondDiscarded = nullptr;
};

[[nodiscard]] static GpuTaskId DeclareStandaloneGraphReadyFrontierUploads(
    void* const rawContext,
    GpuTaskGraph& graph
){
    StandaloneGraphReadyFrontierUploadContext* const context =
        static_cast<StandaloneGraphReadyFrontierUploadContext*>(rawContext)
    ;
    if(
        !context
        || !context->firstDestination
        || !context->secondDestination
        || !context->firstBytes
        || !context->secondBytes
        || context->firstByteCount == 0u
        || context->secondByteCount == 0u
        || !context->recordingStarted
        || !context->firstWorkerIndex
        || !context->secondWorkerIndex
    )
        return {};

    GpuTaskSchedulingHint scheduling;
    scheduling.cost = GpuTaskCostHint::Medium;
    scheduling.forceSubmissionBoundary = true;
    scheduling.allowPacketMerge = false;
    scheduling.allowParallelRecording = true;
    const auto addUpload = [&graph, scheduling](
        const BufferHandle& destinationBuffer,
        void* const bytes,
        const usize byteCount,
        const Name& resourceIdentity,
        const AStringView resourceLabel,
        const Name& taskIdentity,
        const AStringView taskLabel,
        QueueSubmissionToken* const acceptedToken
    ){
        const GpuGraphResourceId destination = graph.importBuffer(
            destinationBuffer,
            GpuGraphResourceDesc{}
                .setIdentity(resourceIdentity)
                .setMarkerLabel(resourceLabel)
                .setType(GpuGraphResourceType::Buffer)
                .setInitialState(ResourceStates::Common)
                .setQueueSharing(destinationBuffer->getDescription().queueSharing)
        );
        const GpuUploadBlobId source = graph.copyUploadData(bytes, byteCount, alignof(u32));
        if(!destination.valid() || !source.valid())
            return GpuTaskId{};

        GpuTaskDesc desc;
        desc
            .setIdentity(taskIdentity)
            .setMarkerLabel(taskLabel)
            .setQueue(GpuQueueRequest{
                GpuQueueCapability::Transfer,
                GpuQueuePreference::Graphics,
                false,
                false,
            })
            .setScheduling(scheduling)
        ;
        return graph.addUploadBufferTask(
            desc,
            GpuUploadBufferTaskDesc{
                .source = source,
                .destination = destination,
                .finalState = ResourceStates::CopyDest,
                .acceptedToken = acceptedToken,
            }
        );
    };

    const GpuTaskId firstUpload = addUpload(
        context->firstDestination,
        context->firstBytes,
        context->firstByteCount,
        Name("tests.standalone_graph_ready_frontier.first_destination"),
        "Standalone Ready Frontier First Destination",
        Name("tests.standalone_graph_ready_frontier.first_upload"),
        "Standalone Ready Frontier First Upload",
        context->firstAcceptedToken
    );
    const GpuTaskId secondUpload = addUpload(
        context->secondDestination,
        context->secondBytes,
        context->secondByteCount,
        Name("tests.standalone_graph_ready_frontier.second_destination"),
        "Standalone Ready Frontier Second Destination",
        Name("tests.standalone_graph_ready_frontier.second_upload"),
        "Standalone Ready Frontier Second Upload",
        context->secondAcceptedToken
    );
    if(!firstUpload.valid() || !secondUpload.valid())
        return {};

    const auto addObserver = [&graph, context, scheduling](
        const Name& identity,
        const AStringView label,
        u32* const observedWorkerIndex,
        bool* const discarded
    ){
        GpuTaskDesc desc;
        desc
            .setIdentity(identity)
            .setMarkerLabel(label)
            .setQueue(GpuQueueRequest{
                GpuQueueCapability::Graphics,
                GpuQueuePreference::Graphics,
                false,
                false,
            })
            .setScheduling(scheduling)
        ;
        return graph.addTask<StandaloneGraphReadyFrontierObserverTask>(
            desc,
            StandaloneGraphReadyFrontierObserverTask::Payload{
                .recordingStarted = context->recordingStarted,
                .observedWorkerIndex = observedWorkerIndex,
                .discarded = discarded,
            }
        );
    };
    const GpuTaskId firstObserver = addObserver(
        Name("tests.standalone_graph_ready_frontier.first_observer"),
        "Standalone Ready Frontier First Observer",
        context->firstWorkerIndex,
        context->firstDiscarded
    );
    const GpuTaskId secondObserver = addObserver(
        Name("tests.standalone_graph_ready_frontier.second_observer"),
        "Standalone Ready Frontier Second Observer",
        context->secondWorkerIndex,
        context->secondDiscarded
    );
    if(!firstObserver.valid() || !secondObserver.valid())
        return {};

    NWB_MEMSET(context->firstBytes, 0, context->firstByteCount);
    NWB_MEMSET(context->secondBytes, 0, context->secondByteCount);
    return secondObserver;
}


// These compact graph tasks model skinning's descriptor-visible compute endpoint. They deliberately perform no
// synthetic native submission: their packet-local barriers publish the required compute states, and the task's
// accepted callback observes the same packet token as its uploads/copies.
struct SkinningGraphSelectorConsumerTask{
    struct Payload{
        GpuGraphResourceId selector;
        GpuGraphResourceId staticInput;
        bool* observedConstantBuffer = nullptr;
        bool* observedStaticInputShaderResource = nullptr;
        QueueSubmissionToken* acceptedToken = nullptr;
    };

    [[nodiscard]] static bool record(
        const Payload& payload,
        CommandList& commandList,
        const GpuTaskRecordContext& context
    ){
        Buffer* const selector = context.taskGraph.bufferForResource(payload.selector);
        Buffer* const staticInput = context.taskGraph.bufferForResource(payload.staticInput);
        if(!selector || !staticInput)
            return false;

        const bool observedConstantBuffer = commandList.getBufferState(selector) == ResourceStates::ConstantBuffer;
        const bool observedStaticInputShaderResource = commandList.getBufferState(staticInput) == ResourceStates::ShaderResource;
        if(payload.observedConstantBuffer)
            *payload.observedConstantBuffer = observedConstantBuffer;
        if(payload.observedStaticInputShaderResource)
            *payload.observedStaticInputShaderResource = observedStaticInputShaderResource;
        return observedConstantBuffer && observedStaticInputShaderResource;
    }

    static void accepted(Payload& payload, const QueueSubmissionToken& token){
        if(payload.acceptedToken)
            *payload.acceptedToken = token;
    }
};


struct SkinningGraphRestStreamConsumerTask{
    struct Payload{
        GpuGraphResourceId position;
        GpuGraphResourceId normal;
        GpuGraphResourceId tangent;
        QueueSubmissionToken* acceptedToken = nullptr;
    };

    [[nodiscard]] static bool record(
        const Payload& payload,
        CommandList& commandList,
        const GpuTaskRecordContext& context
    ){
        Buffer* const position = context.taskGraph.bufferForResource(payload.position);
        Buffer* const normal = context.taskGraph.bufferForResource(payload.normal);
        Buffer* const tangent = context.taskGraph.bufferForResource(payload.tangent);
        if(!position || !normal || !tangent)
            return false;

        return
            commandList.getBufferState(position) == ResourceStates::ShaderResource
            && commandList.getBufferState(normal) == ResourceStates::ShaderResource
            && commandList.getBufferState(tangent) == ResourceStates::ShaderResource
        ;
    }

    static void accepted(Payload& payload, const QueueSubmissionToken& token){
        if(payload.acceptedToken)
            *payload.acceptedToken = token;
    }
};


// The active-pose skinning path has three graph stages: deformation writes all skinned streams as UAVs, bounds and
// repack consume the required streams as SRVs while producing their own UAV outputs, and a finalizer publishes every
// generated stream. This probe is getter-only so packet-lowered barriers are the entire state contract.
struct SkinningGraphStateProbeTask{
    struct Expectation{
        GpuGraphResourceId resource;
        ResourceStates::Mask state = ResourceStates::Unknown;
    };

    struct Payload{
        Expectation expectations[5u] = {};
        usize expectationCount = 0u;
        bool* recorded = nullptr;
        QueueSubmissionToken* acceptedToken = nullptr;
    };

    [[nodiscard]] static bool record(
        const Payload& payload,
        CommandList& commandList,
        const GpuTaskRecordContext& context
    ){
        if(payload.expectationCount == 0u || payload.expectationCount > LengthOf(payload.expectations))
            return false;

        bool ready = true;
        for(usize expectationIndex = 0u; expectationIndex < payload.expectationCount; ++expectationIndex){
            const Expectation& expectation = payload.expectations[expectationIndex];
            Buffer* const buffer = context.taskGraph.bufferForResource(expectation.resource);
            if(!buffer || commandList.getBufferState(buffer) != expectation.state){
                ready = false;
                break;
            }
        }
        if(payload.recorded)
            *payload.recorded = ready;
        return ready;
    }

    static void accepted(Payload& payload, const QueueSubmissionToken& token){
        if(payload.acceptedToken)
            *payload.acceptedToken = token;
    }
};


// The ready-frontier recorder may execute one chunk on its caller and another on a worker. Hold both task thunks
// at a latch after they observe their command-list description, proving each parallel packet received a distinct
// nonzero worker-affined native lease rather than borrowing the serial/default command arena.
struct WorkerAffinedPacketTask{
    struct Payload{
        Latch* recordingStarted = nullptr;
        u32* observedWorkerIndex = nullptr;
        Buffer* expectedBuffer = nullptr;
        ResourceStates::Mask expectedBufferState = ResourceStates::Unknown;
        QueueSubmissionToken* acceptedToken = nullptr;
    };

    [[nodiscard]] static bool record(
        const Payload& payload,
        CommandList& commandList,
        const GpuTaskRecordContext&
    ){
        if(
            !payload.recordingStarted
            || !payload.observedWorkerIndex
            || !payload.expectedBuffer
            || commandList.getBufferState(payload.expectedBuffer) != payload.expectedBufferState
        )
            return false;
        *payload.observedWorkerIndex = commandList.getDescription().recordingWorkerIndex;
        payload.recordingStarted->count_down();
        payload.recordingStarted->wait();
        return commandList.isRecording();
    }

    static void accepted(Payload& payload, const QueueSubmissionToken& token){
        if(payload.acceptedToken)
            *payload.acceptedToken = token;
    }
};


